SELECT CASE WHEN s.rating >= 4.3 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END rating_bucket, COUNT(oi.quantity) quantity_count, COUNT(DISTINCT oi.quantity) unique_products FROM order_items oi LEFT JOIN products p ON oi.product_id = p.id INNER JOIN suppliers s ON s.id = p.supplier_id WHERE s.supplier_name NOT LIKE '%Imports%' GROUP BY CASE WHEN s.rating >= 4.3 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END
